#pragma once

// Tube Lab presets (1.19.0; tone stack and re-levelled for the new power amp in 1.20.0): every
// Tube Lab sound param, so a preset fully sets the stage (not its
// On switch or whether it's in the chain). Each Output was set by measuring the preset through the
// plugin so its RMS on a plucked-guitar test signal matches the dry signal's: switching presets
// doesn't jump in level. Needs the EParams enum (include after NeuralAmpModeler.h).
//
// Enum params are indices: Cap / Cap 2: 0 None, 1 0.68uF, 2 1uF, 3 2.2uF, 4 10uF, 5 25uF;
// Plate Cap / Plate Cap 2: 0 None, 1 47p, 2 100p, 3 220p, 4 470p, 5 1n;
// Couple: 0 2.2n, 1 4.7n, 2 10n, 3 22n, 4 47n, 5 100n.

struct TubePreset
{
  const char* name;
  const char* description;
  struct
  {
    int param;
    double value;
  } values[30];
};

